changeSet.createProcedure:
create function total_amount(barkod character varying, startdate date, finishdate date) returns double precision as
$body$
    declare
        Product_amount double PRECISION;

    begin
        select sum(aduas.miktar)
        into Product_amount
        from aur_depo_urun_adres_stok as aduas
        where aduas.barcode = barkod and aduas.status = true
          and create_date between startDate and finishDate;
        return Product_amount;

    end;

$body$ language plpgsql
